query ArticlePage($where: ArticleFilter, $fallbackWhere: ArticleFilter) {
  allArticle(where: $where) {
    ...Article
  }
  fallbackArticle: allArticle(where: $fallbackWhere) {
    ...Article
  }
}

fragment Article on Article {
  externalTitle
  path {
    current
  }
  authors {
    externalTitle
  }
  description
  publishingDates {
    displayedPublishDate
  }
  bannerMedia {
    sanityImage {
      asset {
        url
      }
    }
  }
  esportsLeague {
    _ref
  }
  contentBlocks {
    __typename
    ... on ContentItemContentBlock {
      ...ContentItem
    }
    ... on MastheadContentBlock {
      ...Masthead
    }
    ... on MediaPromosListContentBlock {
      ...MediaGallery
    }
    ... on QuoteContentBlock {
      ...Quote
    }
    ... on RichTextContentBlock {
      ...RichText
    }
    ... on SeparatorContentBlock {
      ...Separator
    }
    ... on SimpleImageContentBlock {
      ...SimpleImage
    }
    ... on VideoContentBlock {
      ...Video
    }
  }
  translationMetadata {
    translations {
      locale: _key
    }
  }
}

fragment ContentItem on ContentItemContentBlock {
  media {
    ...VideoAsset
  }
}

