query homeEvents(
  $hl: Locale!
  $sport: [Sport]
  $leagues: [ID]
  $tournamentIds: [ID]
  $eventDateStart: Date
  $eventDateEnd: Date
  $eventState: [EventState]
  $eventType: EventType
  $pageSize: Int
  $vodType: [VodType]
  $pageToken: Token
) {
  esports(
    hl: $hl
    sport: $sport
    leagueId: $leagues
    tournamentId: $tournamentIds
    eventDateStart: $eventDateStart
    eventDateEnd: $eventDateEnd
    eventState: $eventState
    eventType: $eventType
    pageSize: $pageSize
    pageToken: $pageToken
  ) {
    events {
      ...HomeEventMatch
      ...HomeEventShow
    }
    pages {
      older
      newer
    }
  }
}

