query GetCompeteTournamentForRiftboundPlayer(
  $tournamentId: String!
  $includeAdminFields: Boolean! = false
) {
  competeTournaments(esportsTournamentIds: [$tournamentId]) {
    ...CompeteRbTournament
  }
}

query OrganizerSummary($id: ID!) {
  organizerSummary(id: $id) {
    id
    name
    physicalAddress {
      googlePlaceId
      formattedAddress
      latitude
      longitude
    }
    phone {
      countryDialingCode
      number
    }
    email
    website
  }
}

query GetCompeteTournamentForRiftboundAdmin(
  $tournamentId: String!
  $includeAdminFields: Boolean! = false
) {
  competeTournamentForOrganizer(esportsTournamentId: $tournamentId) {
    ...CompeteRbTournament
    # Admin-only roster identities for bulk registration's capacity
    # pre-check, kept out of the shared fragment used by public pages.
    # team.players is the populated roster; rosterMembers is not set on
    # registrant teams.
    tournamentRegistrants {
      id
      team {
        players {
          id
          displayName
          tagLine
        }
      }
    }
    # Admin-only for the Event Manager info modal. Resolved server-side to the
    # event's location override, falling back to the organizer's location.
    tournamentLocation {
      formattedAddress
      googlePlaceId
    }
  }
}

query GetRiftboundDeckSubmission($esportsTournamentId: String!) {
  myRiftboundDeckSubmission(esportsTournamentId: $esportsTournamentId) {
    id
    deckText
    submittedAt
    lastSavedAt
  }
}

query RiftboundDeckSubmissionForOrganizer(
  $esportsTournamentId: String!
  $playerId: ID!
) {
  riftboundDeckSubmissionForOrganizer(
    esportsTournamentId: $esportsTournamentId
    playerId: $playerId
  ) {
    id
    playerId
    deckName
    deckText
    lastSavedAt
  }
}

query GetCompeteRbRefreshPoller($tournamentId: String!) {
  t: competeTournamentUpdatedAt(esportsTournamentId: $tournamentId) {
    u: updatedAt
  }
}
